function setCloudStatus(text,ok=false){const el=document.querySelector('#cloudStatus');if(el){el.textContent=text;el.classList.toggle('online',ok)}}
async function fetchJson(url,options={},timeout=12000){const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),timeout);try{const r=await fetch(url,{...options,signal:controller.signal});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||`Erreur ${r.status}`);return d}finally{clearTimeout(timer)}}
async function syncCloud(){setCloudStatus('Synchronisation…');try{const d=await fetchJson('/.netlify/functions/companies',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prospects})},20000);cloudReady=true;setCloudStatus(`Supabase · ${d.synced||prospects.length} prospects`,true)}catch(e){setCloudStatus('Mode local · '+(e.name==='AbortError'?'délai Supabase dépassé':(e.message||'synchronisation impossible')));console.error(e)}}
