async function hydrateCloud(){setCloudStatus('Connexion Supabase…');try{const d=await fetchJson('/.netlify/functions/companies',{},12000);if(Array.isArray(d.prospects)&&d.prospects.length){prospects=d.prospects.map(p=>({id:p.id||crypto.randomUUID(),jobs:p.jobs||[],notes:p.notes||'',contactEmail:p.contactEmail||'',linkedinUrl:p.linkedinUrl||'',...p}));localStorage.setItem('oligartProspects',JSON.stringify(prospects));renderAll();cloudReady=true;setCloudStatus(`Supabase · ${prospects.length} prospects`,true)}else{setCloudStatus('Supabase vide · import en cours…');await syncCloud()}}catch(e){setCloudStatus('Mode local · '+(e.name==='AbortError'?'Supabase trop lent':(e.message||'connexion impossible')));console.error(e)}}
