function esc(v=''){return String(v).replace(/[&<>"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[m]))}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),1800)}
function switchView(id){$$('.view').forEach(v=>v.classList.toggle('active',v.id===id));$$('.nav').forEach(n=>n.classList.toggle('active',n.dataset.view===id));$('#pageTitle').textContent={dashboard:'Vue d’ensemble',pipeline:'Pipeline',today:'Priorités du jour',jobs:'Recrutements',discovery:'Discovery',activity:'Activité',opportunities:'Opportunités pour moi'}[id]}
