function renderMetrics(){const m=[['Prospects',prospects.length],['À contacter',prospects.filter(p=>p.status==='À contacter').length],['Relances',prospects.filter(due).length],['Réponses',prospects.filter(p=>p.status==='Réponse reçue').length],['RDV',prospects.filter(p=>p.status==='RDV pris').length]];$('#metrics').innerHTML=m.map(x=>`<div class="metric"><span>${x[1]}</span><small>${x[0]}</small></div>`).join('');$('#focusCount').textContent=prospects.filter(due).length}
function renderToday(){const list=[...prospects].filter(due).sort((a,b)=>priorityScore(b)-priorityScore(a));const html=list.slice(0,5).map(p=>`<div class="action-row" data-id="${p.id}"><div><strong>${esc(p.company)}</strong><small>${esc(p.status)} · ${esc(p.contact)}</small></div><span class="badge ${p.priority==='A'?'a':''}">${p.score}/100</span></div>`).join('')||'<p class="muted">Aucune relance urgente. Beau luxe.</p>';$('#todayList').innerHTML=html;$('#todayFull').innerHTML=list.map(p=>`<div class="action-row" data-id="${p.id}"><div><strong>${esc(p.company)}</strong><small>${esc(p.why)}</small></div><div><span class="badge hot">${esc(p.next)}</span> <span class="badge a">${p.score}/100</span></div></div>`).join('')||'<p class="muted">Rien à faire aujourd’hui.</p>'}
function renderFunnel(){const max=Math.max(...STATUSES.map(s=>prospects.filter(p=>p.status===s).length),1);$('#funnel').innerHTML=STATUSES.slice(0,6).map(s=>{const n=prospects.filter(p=>p.status===s).length;return`<div class="funnel-row"><span>${s}</span><div class="bar"><i style="width:${n/max*100}%"></i></div><b>${n}</b></div>`}).join('')}
function row(p){return `<tr data-id="${p.id}"><td><span class="badge ${p.priority==='A'?'a':''}">${p.priority}</span></td><td><strong>${esc(p.company)}</strong><br><small class="muted">${esc(p.model)}</small></td><td>${esc(p.sector)}</td><td class="score">${p.score}</td><td>${esc(p.status)}</td><td>${esc(p.contact)}</td><td>${p.next||'—'}</td></tr>`}
function table(items){return `<table class="data-table"><thead><tr><th>Priorité</th><th>Entreprise</th><th>Secteur</th><th>Score</th><th>Statut</th><th>Décideur</th><th>Relance</th></tr></thead><tbody>${items.map(row).join('')}</tbody></table>`}
function filteredProspects(){const q=$('#search').value?.toLowerCase()||'',s=$('#statusFilter').value,pr=$('#priorityFilter').value;return prospects.filter(p=>(!q||[p.company,p.sector,p.model,p.contact].join(' ').toLowerCase().includes(q))&&(!s||p.status===s)&&(!pr||p.priority===pr))}
function renderKanban(){const board=$('#kanbanBoard');if(!board)return;const visibleStatuses=STATUSES.filter(s=>s!=='Perdu');const filtered=filteredProspects();board.innerHTML=visibleStatuses.map(status=>{const items=filtered.filter(p=>p.status===status).sort((a,b)=>priorityScore(b)-priorityScore(a));return `<section class="kanban-column" data-status="${esc(status)}"><header><div><strong>${esc(status)}</strong><small>${items.length} prospect${items.length>1?'s':''}</small></div></header><div class="kanban-drop" data-status="${esc(status)}">${items.map(p=>`<article class="kanban-card" draggable="true" data-id="${p.id}"><div class="kanban-card-top"><span class="badge ${p.priority==='A'?'a':''}">${p.priority}</span><span class="score">${p.score}</span></div><strong>${esc(p.company)}</strong><small>${esc(p.sector)}</small><p>${esc(p.contact||'Décideur à identifier')}</p>${p.next?`<span class="kanban-date ${due(p)?'urgent':''}">${due(p)?'Relance ':''}${esc(p.next)}</span>`:''}</article>`).join('')||'<div class="kanban-empty">Dépose un prospect ici</div>'}</div></section>`}).join('');
  $$('.kanban-card').forEach(card=>{card.ondragstart=e=>{e.dataTransfer.setData('text/plain',card.dataset.id);card.classList.add('dragging')};card.ondragend=()=>card.classList.remove('dragging');card.onclick=()=>openDrawer(card.dataset.id)});
  $$('.kanban-drop').forEach(zone=>{zone.ondragover=e=>{e.preventDefault();zone.classList.add('drag-over')};zone.ondragleave=()=>zone.classList.remove('drag-over');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('drag-over');const id=e.dataTransfer.getData('text/plain'),p=prospects.find(x=>x.id===id);if(!p||p.status===zone.dataset.status)return;const previous=p.status;p.status=zone.dataset.status;p.last=today(0);if(p.status==='Contacté'&&!p.next)p.next=today(4);if(['Gagné','Perdu'].includes(p.status))p.next='';p.notes=(p.notes||'')+`
[${today(0)}] Statut : ${previous} → ${p.status}`;save();toast(`${p.company} déplacé vers ${p.status}`)}})}
function renderTables(){const top=[...prospects].sort((a,b)=>priorityScore(b)-priorityScore(a)).slice(0,8);$('#topTable').innerHTML=table(top);$('#pipelineTable').innerHTML=table(filteredProspects());renderKanban()}
function renderJobs(){const tracked=prospects.filter(p=>p.jobsUrl||p.jobs?.length);const total=tracked.reduce((n,p)=>n+(p.jobs?.length||0),0),relevant=tracked.reduce((n,p)=>n+(p.jobs?.filter(j=>j.relevant).length||0),0);const liveCareer=(careerOpportunities||[]).filter(j=>j.score>=65).slice(0,40);$('#jobsSummary').innerHTML=[['URLs suivies',tracked.filter(p=>p.jobsUrl).length],['Offres CRM',total],['Signaux pertinents',relevant],['Offres profil Rodolph',liveCareer.length]].map(x=>`<div class="metric"><span>${x[1]}</span><small>${x[0]}</small></div>`).join('');const trackedHtml=tracked.map(p=>`<article class="job-card" data-id="${p.id}"><p class="eyebrow">${esc(p.company)}</p><div class="job-count">${p.jobs?.length||0}</div><p>${(p.jobs?.filter(j=>j.relevant).length||0)} offre(s) Sales / Marketing / Growth pertinente(s)</p><button class="mini accent" data-scan="${p.id}">Analyser les recrutements</button></article>`).join('');const liveHtml=liveCareer.map((j,i)=>`<article class="job-card opportunity-card"><p class="eyebrow">${esc(j.company)} · ${esc(j.source||'Source publique')}</p><div class="job-count">${j.score}</div><strong>${esc(j.title)}</strong><p>${esc(j.location||'Localisation non précisée')}</p><div class="inline-actions"><button class="mini" data-live-open="${i}">Voir l’annonce</button><button class="mini accent" data-live-contact="${i}">Candidater</button></div></article>`).join('');$('#jobsGrid').innerHTML=trackedHtml+liveHtml||'<div class="panel"><p class="muted">Clique sur « Rechercher les offres » pour détecter les opportunités média / tech / internet correspondant à ton profil.</p><button id="jobsLoadCareer" class="primary">Rechercher les offres</button></div>';$$('[data-scan]').forEach(b=>b.onclick=()=>scanJobs(b.dataset.scan));$$('[data-live-open]').forEach(b=>b.onclick=()=>window.open(liveCareer[Number(b.dataset.liveOpen)].url,'_blank'));$$('[data-live-contact]').forEach(b=>b.onclick=()=>openCareerContact(liveCareer[Number(b.dataset.liveContact)]));const load=$('#jobsLoadCareer');if(load)load.onclick=async()=>{await loadOpportunities();renderJobs()}}
function normalizeDiscovery(x){
  const parts=String(x.signal_description||'').split(' || ');
  return {id:x.id,company:x.company_name,sector:parts[1]||'Startup / Scale-up',model:parts[2]||'B2B',priority:Number(x.opportunity_score||0)>=80?'A':'B',score:Number(x.opportunity_score||65),contact:'CEO / Fondateur',why:parts[0]||'Signal de croissance détecté publiquement.',website:x.website||x.source_url||'',source:x.source||'',sourceUrl:x.source_url||'',detectedAt:x.detected_at||'',signals:[x.signal_type||'signal',x.source||'source']};
}
async function loadDiscovery({refresh=false}={}){
  const btn=$('#refreshDiscovery');if(btn){btn.disabled=true;btn.textContent=refresh?'Recherche en cours…':'Chargement…'}
  try{
    if(refresh){const r=await fetch('/.netlify/functions/discovery',{method:'POST'});const d=await r.json();if(!r.ok)throw Error(d.error||'Actualisation impossible');toast(`${d.added} nouveau(x) signal(aux) ajouté(s)`)}
    const r=await fetch('/.netlify/functions/discovery');const d=await r.json();if(!r.ok)throw Error(d.error||'Discovery inaccessible');
    discoveryItems=(d.items||[]).map(normalizeDiscovery);discoveryLastSync=new Date().toISOString();renderDiscovery();
  }catch(e){console.error(e);toast(e.message);discoveryItems=discoveryItems.length?discoveryItems:discoverySeed;renderDiscovery()}
  finally{if(btn){btn.disabled=false;btn.textContent='Actualiser maintenant'}}
}
function renderDiscovery(){const q=$('#discoverySearch')?.value?.toLowerCase()||'',m=$('#discoveryModel')?.value||'';const existing=new Set(prospects.map(p=>p.company.toLowerCase()));const source=discoveryItems.length?discoveryItems:discoverySeed;const items=source.filter(x=>!existing.has(x.company.toLowerCase())&&(!q||[x.company,x.sector,x.why].join(' ').toLowerCase().includes(q))&&(!m||x.model===m));$('#discoveryGrid').innerHTML=items.map((x,i)=>`<article class="panel discovery-card"><div><p class="eyebrow">${esc(x.sector)} · ${esc(x.model)}</p><h3>${esc(x.company)}</h3><p class="muted">${esc(x.why)}</p>${x.source?`<p class="muted tiny">Source : ${esc(x.source)} · ${x.detectedAt?new Date(x.detectedAt).toLocaleDateString('fr-FR'):''}</p>`:''}</div><div class="signals">${(x.signals||[]).map(s=>`<span class="badge">${esc(s)}</span>`).join('')}</div><footer><span class="badge a">${x.score}/100</span><div class="inline-actions">${x.sourceUrl?`<button class="mini" data-open-source="${i}">Voir la source</button>`:''}<button class="mini accent" data-add-discovery="${i}">Ajouter au pipeline</button></div></footer></article>`).join('')||'<div class="panel"><p class="muted">Aucune nouvelle suggestion. Lance une actualisation.</p></div>';$$('[data-add-discovery]').forEach(b=>b.onclick=()=>addDiscovery(items[Number(b.dataset.addDiscovery)]));$$('[data-open-source]').forEach(b=>b.onclick=()=>window.open(items[Number(b.dataset.openSource)].sourceUrl,'_blank'))}
function addDiscovery(x){if(!x)return;prospects.unshift({id:crypto.randomUUID(),company:x.company,sector:x.sector,model:x.model,priority:x.priority,score:x.score,status:'À contacter',contact:x.contact,why:x.why,website:x.website,contactEmail:'',linkedinUrl:'',jobsUrl:'',last:'',next:today(0),notes:`Ajouté depuis Discovery${x.source?' — '+x.source:''}`,jobs:[]});logActivity('Discovery',x.company,'Ajout au pipeline');save();renderDiscovery();toast(`${x.company} ajouté`)}
$('#discoverySearch').oninput=renderDiscovery;$('#discoveryModel').onchange=renderDiscovery;
$('#refreshDiscovery').onclick=()=>loadDiscovery({refresh:true});
$('#addAllDiscovery').onclick=()=>{const existing=new Set(prospects.map(p=>p.company.toLowerCase()));const source=discoveryItems.length?discoveryItems:discoverySeed;const add=source.filter(x=>x.priority==='A'&&!existing.has(x.company.toLowerCase())).slice(0,25);add.forEach(addDiscovery);toast(`${add.length} cibles ajoutées`)};
$('#clearActivity').onclick=()=>{if(confirm('Vider l’historique local ?')){activityLog=[];localStorage.setItem('oligartActivity','[]');renderActivity()}};
$('#scanAllJobs').onclick=async()=>{const list=prospects.filter(p=>p.jobsUrl);if(!list.length)return toast('Aucune URL careers configurée');let done=0;$('#scanAllJobs').disabled=true;for(const p of list.slice(0,30)){try{const r=await fetch('/.netlify/functions/jobs?url='+encodeURIComponent(p.jobsUrl));const d=await r.json();if(r.ok){p.jobs=d.jobs||[];if(p.jobs.some(j=>j.relevant))p.score=Math.min(100,p.score+4);done++}}catch(e){}}logActivity('Recrutements','Analyse en lot',`${done}/${Math.min(list.length,30)} pages analysées`);save();$('#scanAllJobs').disabled=false;toast(`${done} pages analysées`)};
$('#backupBtn').onclick=()=>{const payload={version:DATA_VERSION,exportedAt:new Date().toISOString(),prospects,activityLog};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));a.download=`oligart-backup-${today(0)}.json`;a.click();logActivity('Sauvegarde','Base CRM','Sauvegarde JSON créée')};
