function getCv(){try{return JSON.parse(localStorage.getItem('oligartCv')||'null')}catch(e){return null}}
function setCvBadge(){const cv=getCv(),b=$('#cvBadge'),n=$('#cvFileName');if(b){b.textContent=cv?`CV chargé · ${cv.name}`:'CV non chargé';b.classList.toggle('a',!!cv)}if(n)n.textContent=cv?cv.name:'Choisir le CV'}
function applicationTemplate(j){return {subject:`Candidature — ${j.title} — Rodolph Menten`,text:`Bonjour,\n\nJe vous contacte au sujet du poste de ${j.title} chez ${j.company}.\n\nJ’ai dirigé et développé des activités en France dans les univers média, publicité digitale, tech et marketplaces, avec une expérience forte en lancement de marché, structuration commerciale, management d’équipes et développement de grands comptes.\n\nJe serais ravi d’échanger avec vous sur les enjeux du poste et sur la manière dont mon expérience pourrait contribuer au développement de ${j.company}.\n\nVous pouvez découvrir mon activité et plusieurs éléments de mon parcours ici : ${OLIGART_SITE}\n\nJe joins également mon CV.\n\nBien à vous,\nRodolph Menten\nrodolph.menten@oligart.fr`}}
function filteredOpportunities(){const q=$('#opportunitySearch')?.value?.toLowerCase()||'',loc=$('#opportunityLocation')?.value||'',min=Number($('#opportunityLevel')?.value||0);return careerOpportunities.filter(j=>(!q||[j.title,j.company,j.location,j.description].join(' ').toLowerCase().includes(q))&&(!loc||j.location.toLowerCase().includes(loc)||(loc==='remote'&&j.remote))&&j.score>=min)}
function renderOpportunities(){const items=filteredOpportunities();const el=$('#opportunitiesGrid');if(!el)return;$('#opportunitiesMetrics').innerHTML=[['Opportunités',careerOpportunities.length],['Très pertinentes',careerOpportunities.filter(x=>x.score>=80).length],['France / Paris',careerOpportunities.filter(x=>/france|paris/i.test(x.location)).length],['Sources',new Set(careerOpportunities.map(x=>x.source)).size]].map(x=>`<div class="metric"><span>${x[1]}</span><small>${x[0]}</small></div>`).join('');el.innerHTML=items.map((j,i)=>`<article class="panel opportunity-card"><div><div class="opportunity-meta"><span class="badge ${j.score>=80?'a':''}">${j.score}/100</span><span class="badge">${esc(j.source)}</span>${j.remote?'<span class="badge">Remote</span>':''}</div><p class="eyebrow">${esc(j.company)}</p><h3 class="job-title">${esc(j.title)}</h3><p class="muted">${esc(j.location||'Localisation non précisée')}</p></div><div class="fit-reasons">${(j.reasons||[]).map(r=>`<span>✓ ${esc(r)}</span>`).join('')}</div><p class="muted">${esc((j.description||'').slice(0,240))}${j.description?.length>240?'…':''}</p><footer><span class="source-label">${j.published?new Date(j.published).toLocaleDateString('fr-FR'):''}</span><div class="inline-actions"><button class="mini" data-job-open="${i}">Voir l’annonce</button><button class="mini accent" data-job-contact="${i}">Contacter</button></div></footer></article>`).join('')||'<div class="panel"><p class="muted">Aucune opportunité ne correspond aux filtres actuels.</p></div>';$$('[data-job-open]').forEach(b=>b.onclick=()=>window.open(items[Number(b.dataset.jobOpen)].url,'_blank'));$$('[data-job-contact]').forEach(b=>b.onclick=()=>openCareerContact(items[Number(b.dataset.jobContact)]))}
async function loadOpportunities(){const btn=$('#refreshOpportunities');if(btn){btn.disabled=true;btn.textContent='Recherche en cours…'}try{const d=await fetchJson('/.netlify/functions/opportunities',{},18000);careerOpportunities=d.jobs||[];careerUpdatedAt=d.updatedAt||'';localStorage.setItem('oligartCareerOpportunities',JSON.stringify({jobs:careerOpportunities,updatedAt:careerUpdatedAt}));renderOpportunities();renderJobs();toast(`${careerOpportunities.length} opportunités analysées`)}catch(e){const cached=JSON.parse(localStorage.getItem('oligartCareerOpportunities')||'{"jobs":[]}');careerOpportunities=cached.jobs||[];renderOpportunities();toast(e.message)}finally{if(btn){btn.disabled=false;btn.textContent='Rechercher maintenant'}}}
function openCareerContact(j){const t=applicationTemplate(j),cv=getCv();const content=`<p class="eyebrow">CANDIDATURE DIRECTE</p><h2>${esc(j.company)}</h2><p class="muted">${esc(j.title)} · ${esc(j.location)}</p><div class="contact-box"><label>Email du recruteur / RH<input id="careerEmail" class="input" type="email" placeholder="recrutement@entreprise.com"></label><label>Profil LinkedIn<input id="careerLinkedin" class="input" placeholder="https://linkedin.com/in/..."></label><label class="wide">Objet<input id="careerSubject" class="input" value="${esc(t.subject)}"></label><label class="wide">Message<textarea id="careerText" class="input">${esc(t.text)}</textarea></label></div><div class="security-note"><strong>Pièces et liens</strong><p>Site Oligart inclus automatiquement : <a href="${OLIGART_SITE}" target="_blank">${OLIGART_SITE}</a><br>${cv?'CV prêt à être joint : '+esc(cv.name):'Aucun CV chargé — ajoute-le dans Paramètres email.'}</p></div><div class="apply-actions"><button id="careerSend" class="primary">Envoyer depuis Oligart</button><button id="careerAirmail" class="mini">Ouvrir dans Airmail</button><button id="careerCopyLinkedin" class="mini">Copier pour LinkedIn</button><button id="careerFindContact" class="mini">Trouver le recruteur</button></div>`;$('#drawerContent').innerHTML=content;$('#drawer').classList.add('open');$('#careerFindContact').onclick=()=>window.open(`https://www.google.com/search?q=${encodeURIComponent(j.company+' recruiter talent acquisition LinkedIn')}`,'_blank');$('#careerCopyLinkedin').onclick=async()=>{await navigator.clipboard.writeText($('#careerText').value);const u=$('#careerLinkedin').value;window.open(u||`https://www.linkedin.com/search/results/people/?keywords=${encodeURIComponent(j.company+' talent acquisition')}`,'_blank');toast('Message copié')};$('#careerAirmail').onclick=()=>{const to=$('#careerEmail').value,sub=$('#careerSubject').value,txt=$('#careerText').value;location.href=`mailto:${encodeURIComponent(to)}?subject=${encodeURIComponent(sub)}&body=${encodeURIComponent(txt)}`};$('#careerSend').onclick=async()=>{const to=$('#careerEmail').value.trim();if(!to)return toast('Ajoute l’email du recruteur');const button=$('#careerSend');button.disabled=true;button.textContent='Envoi…';try{const body={to,subject:$('#careerSubject').value,text:$('#careerText').value};if(cv)body.attachment={filename:cv.name,content:cv.data};const r=await fetch('/.netlify/functions/send-email',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Error(d.error||'Envoi impossible');logActivity('Candidature',j.company,j.title);toast('Candidature envoyée');button.textContent='Envoyé ✓'}catch(e){toast(e.message);button.disabled=false;button.textContent='Envoyer depuis Oligart'}}}
$('#refreshOpportunities').onclick=loadOpportunities;$('#opportunitySearch').oninput=renderOpportunities;$('#opportunityLocation').onchange=renderOpportunities;$('#opportunityLevel').onchange=renderOpportunities;
$('#cvInput').onchange=e=>{const file=e.target.files?.[0];if(!file)return;if(file.type!=='application/pdf')return toast('Le CV doit être un PDF');if(file.size>5*1024*1024)return toast('CV trop lourd : maximum 5 Mo');const reader=new FileReader();reader.onload=()=>{localStorage.setItem('oligartCv',JSON.stringify({name:file.name,data:reader.result,updatedAt:new Date().toISOString()}));setCvBadge();toast('CV enregistré')};reader.readAsDataURL(file)};
$('#removeCv').onclick=()=>{localStorage.removeItem('oligartCv');setCvBadge();toast('CV retiré')};
setCvBadge();
try{const cached=JSON.parse(localStorage.getItem('oligartCareerOpportunities')||'{"jobs":[]}');careerOpportunities=cached.jobs||[]}catch(e){}
renderOpportunities();

const cloudEl=document.querySelector('#cloudStatus');if(cloudEl){cloudEl.title='Cliquer pour retenter la synchronisation';cloudEl.style.cursor='pointer';cloudEl.onclick=hydrateCloud;}
